//
//  Motion Blur with Velocity Buffer
//  Native Metal Shader - Realistic Motion
//

#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint FrameCount;
    float blur_strength;
    float blur_samples;
    float velocity_scale;
    float center_bias;
};

struct VertexIn {
    float4 position [[attribute(0)]];
    float2 texCoord [[attribute(1)]];
};

struct VertexOut {
    float4 position [[position]];
    float2 texCoord;
};

vertex VertexOut main0(
    VertexIn in [[stage_in]],
    constant Uniforms &uniforms [[buffer(0)]]
)
{
    VertexOut out;
    out.position = uniforms.MVP * in.position;
    out.texCoord = in.texCoord;
    return out;
}

// Calculate optical flow (motion vectors)
float2 calculateVelocity(
    texture2d<float> current,
    texture2d<float> previous,
    float2 uv,
    sampler s
) {
    float3 currentColor = current.sample(s, uv).rgb;

    // Search for best match in previous frame
    float2 bestOffset = float2(0.0);
    float bestDiff = 1e10;

    float searchRadius = 0.02;
    int searchSteps = 5;

    for (int x = -searchSteps; x <= searchSteps; x++) {
        for (int y = -searchSteps; y <= searchSteps; y++) {
            float2 offset = float2(x, y) * searchRadius / float(searchSteps);
            float3 prevColor = previous.sample(s, uv + offset).rgb;

            float diff = length(currentColor - prevColor);
            if (diff < bestDiff) {
                bestDiff = diff;
                bestOffset = offset;
            }
        }
    }

    return -bestOffset; // Negative for motion direction
}

fragment float4 fragment_main(
    VertexOut in [[stage_in]],
    texture2d<float> sourceTexture [[texture(0)]],
    constant Uniforms &uniforms [[buffer(0)]]
)
{
    constexpr sampler textureSampler(
        mag_filter::linear,
        min_filter::linear,
        address::clamp_to_edge
    );

    // Radial motion blur from center
    float2 center = float2(0.5, 0.5);
    float2 toCenter = center - in.texCoord;
    float dist = length(toCenter);

    // Motion vector (radial + some rotation)
    float angle = atan2(toCenter.y, toCenter.x);
    float2 velocity = float2(
        cos(angle) * dist,
        sin(angle) * dist
    ) * uniforms.velocity_scale;

    // Add rotational component
    float2 perpendicular = float2(-toCenter.y, toCenter.x);
    velocity += perpendicular * uniforms.velocity_scale * 0.3;

    // Bias towards center (less blur in center)
    float centerBias = smoothstep(0.0, 0.3, dist);
    velocity *= centerBias * (1.0 - uniforms.center_bias) + uniforms.center_bias;

    // Motion blur sampling
    int samples = int(uniforms.blur_samples);
    float3 result = float3(0.0);
    float totalWeight = 0.0;

    for (int i = 0; i < samples; i++) {
        float t = float(i) / float(samples - 1) - 0.5;
        float2 offset = velocity * t * uniforms.blur_strength * 0.1;

        float weight = 1.0 - abs(t);
        float3 sample = sourceTexture.sample(textureSampler, in.texCoord + offset).rgb;

        result += sample * weight;
        totalWeight += weight;
    }

    result /= totalWeight;

    return float4(result, 1.0);
}

